// Frakment chat engine — AI SDK v7 adapter helpers.
// Exports: getMessageText, getToolCalls, FrameworkAdapter, createAiSdkAdapter.

import { defaultCreateMessage } from "./builder";
import { eventsFromParts, materializeParts } from "./envelope";
import type { UIDataTypes, UIMessage, UIMessagePart, UITools } from "./types";

// ============================================================
// getMessageText (T) — extract concatenated text parts
// ============================================================

export function getMessageText(message: UIMessage): string {
  if (!Array.isArray(message.parts)) {
    return "";
  }
  return message.parts
    .filter(
      (part): part is { type: "text"; text: string } =>
        part.type === "text" &&
        typeof (part as { text?: string }).text === "string"
    )
    .map((part) => part.text)
    .join("");
}

// ============================================================
// getToolCalls (A) — extract tool call descriptors from a message
// ============================================================

export interface ToolCallDescriptor {
  approval?: {
    id: string;
    approved?: boolean;
    reason?: string;
  };
  dynamic: boolean;
  errorText: string | undefined;
  input: unknown;
  name: string;
  output: unknown;
  state: string;
  toolCallId: string;
}

function fromToolPart(
  part: {
    type: string;
    toolCallId: string;
    input?: unknown;
    output?: unknown;
    errorText?: string;
    state: string;
    approval?: { id: string; approved?: boolean; reason?: string };
  },
  name: string,
  dynamic: boolean
): ToolCallDescriptor {
  return {
    approval: part.approval,
    dynamic,
    errorText: part.state === "output-error" ? part.errorText : undefined,
    input: part.input,
    name,
    output: part.state === "output-available" ? part.output : undefined,
    state: part.state,
    toolCallId: part.toolCallId,
  };
}

export function getToolCalls(message: UIMessage): ToolCallDescriptor[] {
  const out: ToolCallDescriptor[] = [];
  for (const part of message.parts) {
    if (part.type === "dynamic-tool") {
      out.push(
        fromToolPart(
          part as never,
          (part as { toolName: string }).toolName,
          true
        )
      );
      continue;
    }
    if (part.type.startsWith("tool-") && "toolCallId" in part) {
      out.push(
        fromToolPart(part as never, part.type.replace("tool-", ""), false)
      );
    }
  }
  return out;
}

// ============================================================
// FrameworkAdapter interface (dependency injection for ChatBuilder)
// ============================================================

export interface FrameworkAdapter {
  createMessage: typeof defaultCreateMessage;
  eventsFromParts: typeof eventsFromParts;
  getMessageId: (message: UIMessage) => string;
  getMessageMetadata: (message: UIMessage) => unknown;
  getMessageParts: (
    message: UIMessage
  ) => UIMessagePart<UIDataTypes, UITools>[];
  getMessageRole: (message: UIMessage) => "user" | "assistant" | "system";
  getMessageText: (message: UIMessage) => string;
  getToolCalls: (message: UIMessage) => ToolCallDescriptor[];
  materializeParts: typeof materializeParts;
}

export function createAiSdkAdapter(): FrameworkAdapter {
  return {
    createMessage: defaultCreateMessage,
    eventsFromParts,
    getMessageId: (message) => message.id,
    getMessageMetadata: (message) => message.metadata,
    getMessageParts: (message) => message.parts,
    getMessageRole: (message) => message.role,
    getMessageText,
    getToolCalls,
    materializeParts,
  };
}

// Frakment chat engine â€” ChatBuilder: turn scripting, continuation, transport.

import {
  eventsFromParts,
  eventsToEnvelope,
  materializeParts,
} from "./envelope";
import { createIdGenerator } from "./ids";
import { createPayloadFactory } from "./payloads";
import { streamFromEnvelope } from "./stream";
import type {
  AiSdkChat,
  ChatAssistantOptions,
  ChatEvent,
  ChatTransport,
  ChatTransportOptions,
  ChatUserOptions,
  CreateChatOptions,
  DataTypes,
  ToolSet,
  UIDataTypes,
  UIMessage,
  UIMessagePart,
  UITools,
} from "./types";
import { deepClone } from "./utils";
import type { WriterContext } from "./writer";
import { createEventWriter, DEFAULT_ERROR, DEFAULT_TEXT } from "./writer";

export const DEFAULT_USER_TEXT = "Summarize the uploaded receipt.";

export interface Turn {
  continuation?: boolean;
  events: ChatEvent[];
  lastEvents?: ChatEvent[];
  message?: UIMessage;
  messageId: string;
  metadata?: unknown;
  resolve?: unknown;
  role: "user" | "assistant";
}

export type MessageFactory = (input: {
  id: string;
  role: "user" | "assistant";
  metadata: unknown;
  parts: UIMessagePart<UIDataTypes, UITools>[];
}) => UIMessage;

export function defaultCreateMessage(input: {
  id: string;
  role: "user" | "assistant";
  metadata: unknown;
  parts: UIMessagePart<UIDataTypes, UITools>[];
}): UIMessage {
  if (input.role === "user") {
    const parts = input.parts.map((part) => {
      if (part.type !== "text") {
        return part;
      }
      const { state: _ignored, ...rest } = part as UIMessagePart<
        UIDataTypes,
        UITools
      > & { state?: unknown };
      return rest as UIMessagePart<UIDataTypes, UITools>;
    });
    return { id: input.id, metadata: input.metadata, parts, role: "user" };
  }
  return {
    id: input.id,
    metadata: input.metadata,
    parts: input.parts,
    role: "assistant",
  };
}

export function createMetadataFactory(
  now?: Date | string
): () => Record<string, unknown> {
  const date =
    now instanceof Date ? now : new Date(now ?? "2026-01-01T00:00:00.000Z");
  return () => ({ createdAt: date.toISOString() });
}

// ============================================================
// createChatBuilder â€” core methods (Phase 4)
// Transport + continuation will be added in Phase 5/6.
// ============================================================

function getTextOf(message: UIMessage): string {
  return message.parts
    .filter((p): p is { type: "text"; text: string } => p.type === "text")
    .map((p) => p.text)
    .join("");
}

// ============================================================
// Continuation helpers â€” pending tools, fallback, resolve turn, continuation materialization.
// ============================================================

interface PendingToolRaw {
  approval?: Extract<ChatEvent, { kind: "tool-approval-request" }>;
  input: Extract<ChatEvent, { kind: "tool-input" }>;
}

function getPendingToolsRaw(events: readonly ChatEvent[]): PendingToolRaw[] {
  const resolved = new Set<string>();
  for (const event of events) {
    if (
      (event.kind === "tool-output" && !event.preliminary) ||
      event.kind === "tool-error" ||
      event.kind === "tool-denied"
    ) {
      resolved.add(event.toolCallId);
    }
  }
  const out: PendingToolRaw[] = [];
  for (const event of events) {
    if (event.kind === "tool-input" && !resolved.has(event.toolCallId)) {
      out.push({
        approval: events.find(
          (e) =>
            e.kind === "tool-approval-request" &&
            e.toolCallId === event.toolCallId
        ) as Extract<ChatEvent, { kind: "tool-approval-request" }> | undefined,
        input: event,
      });
    }
  }
  return out;
}

function _toPendingToolCall(
  raw: PendingToolRaw,
  summary:
    | {
        toolCallId?: string;
        input?: unknown;
        output?: unknown;
        state?: string;
        approval?: { approved?: boolean };
      }
    | undefined
): {
  name: string;
  toolCallId: string;
  input: unknown;
  output: unknown;
  approved?: boolean;
  denied?: boolean;
} {
  const approvalApproved = raw.approval
    ? summary?.approval?.approved
    : undefined;

  let output: unknown;
  if (raw.approval) {
    output = approvalApproved === true ? raw.approval.output : undefined;
  } else if (summary?.state === "output-available") {
    const { output: summaryOutput } = summary;
    output = summaryOutput;
  } else {
    output = undefined;
  }

  const approvalFields = raw.approval
    ? {
        approved: approvalApproved === true,
        denied: approvalApproved === false,
      }
    : {};

  return {
    input: summary?.input ?? raw.input.input,
    name: raw.input.name,
    output,
    toolCallId: raw.input.toolCallId,
    ...approvalFields,
  };
}

function _defaultMetadata(
  now: Date | string | undefined
): () => Record<string, unknown> {
  const date =
    now instanceof Date ? now : new Date(now ?? "2026-01-01T00:00:00.000Z");
  return () => ({ createdAt: date.toISOString() });
}

function findNextAssistant(turns: readonly Turn[], from: number): number {
  for (let i = from; i < turns.length; i += 1) {
    if (turns[i]?.role === "assistant") {
      return i;
    }
  }
  return -1;
}

function lastAssistantIndex(turns: readonly Turn[], upTo: number): number {
  for (let i = upTo - 1; i >= 0; i -= 1) {
    if (turns[i]?.role === "assistant") {
      return i;
    }
  }
  return -1;
}

function resolveTurnIndex(
  turns: readonly Turn[],
  messages: readonly UIMessage[],
  matchTranscript: (msgs: readonly UIMessage[]) => number,
  regenerateId: string | undefined
): number {
  if (regenerateId) {
    const idx = turns.findIndex((t) => t.messageId === regenerateId);
    if (turns[idx]?.role === "assistant") {
      return idx;
    }
    if (idx !== -1) {
      return findNextAssistant(turns, idx + 1);
    }
  }
  const matched = matchTranscript(messages);
  return findNextAssistant(turns, matched + 1);
}

function hasContinuation(turns: readonly Turn[]): boolean {
  const last = turns.at(-1);
  if (last?.role !== "assistant") {
    return false;
  }
  return (
    last.resolve !== undefined || getPendingToolsRaw(last.events).length > 0
  );
}

function buildFallbackResponse(
  fallback: NonNullable<
    ChatTransportOptions<
      UIMessage,
      UIMessagePart<UIDataTypes, UITools>
    >["fallback"]
  >,
  messages: readonly UIMessage[],
  _writerContext: WriterContext,
  createMetadata: () => Record<string, unknown>,
  ids: ReturnType<typeof createIdGenerator>,
  materialize: (
    input:
      | string
      | UIMessagePart<UIDataTypes, UITools>[]
      | ((ctx: unknown) => void),
    events: ChatEvent[]
  ) => UIMessagePart<UIDataTypes, UITools>[]
): Turn {
  const events: ChatEvent[] = [];
  const input =
    typeof fallback === "function"
      ? (ctx: unknown) => fallback({ ...(ctx as object), messages } as never)
      : fallback;
  const parts = materialize(input as never, events);
  const metadata = createMetadata();
  const id = ids.nextMessageId();
  return {
    events,
    message: defaultCreateMessage({ id, metadata, parts, role: "assistant" }),
    messageId: id,
    metadata,
    role: "assistant",
  };
}

export function createChatBuilder(options: CreateChatOptions = {}): AiSdkChat {
  const ids = createIdGenerator(options);
  const payloads = createPayloadFactory(ids);
  const createMetadata = createMetadataFactory(options.now);
  const writerContext: WriterContext = { ids, payloads };

  const turns: Turn[] = [];
  const pendingSleeps: ChatEvent[] = [];

  function reserveFromEvents(events: ChatEvent[]): void {
    for (const event of events) {
      if (
        event.kind === "tool-input" ||
        event.kind === "tool-output" ||
        event.kind === "tool-error" ||
        event.kind === "tool-denied" ||
        event.kind === "tool-approval-request"
      ) {
        ids.reserveToolCallId(event.toolCallId);
      }
      if (event.kind === "tool-approval-request") {
        ids.reserveApprovalId(event.approvalId);
      }
      if (event.kind === "source-url" || event.kind === "source-document") {
        ids.reserveSourceId(event.part.sourceId);
      }
    }
  }

  function nextMessageIdOrReserve(id?: string): string {
    if (id !== undefined) {
      ids.reserveMessageId(id);
      return id;
    }
    return ids.nextMessageId();
  }

  function flushPendingSleeps(): ChatEvent[] {
    const sleeps = pendingSleeps.splice(0);
    return [...sleeps];
  }

  function pushTurn(turn: Turn): AiSdkChat {
    turns.push(turn);
    return builder;
  }

  function matchTranscript(messages: readonly UIMessage[]): number {
    const transcriptIds = new Set(messages.map((m) => m.id));
    let lastMatch = -1;
    for (let i = 0; i < turns.length; i += 1) {
      const turn = turns[i];
      if (turn && transcriptIds.has(turn.messageId)) {
        lastMatch = i;
      }
    }
    if (lastMatch === -1) {
      const lastMsg = messages.at(-1);
      if (lastMsg) {
        lastMatch = turns.findIndex(
          (t) =>
            t.message !== undefined &&
            t.role === lastMsg.role &&
            getTextOf(t.message) === getTextOf(lastMsg)
        );
      }
    }
    return lastMatch;
  }

  function findNextUser(messages: readonly UIMessage[]): Turn | undefined {
    const start = matchTranscript(messages);
    return turns.slice(start + 1).find((t) => t.role === "user");
  }

  function materializeAssistantInput(
    input:
      | string
      | UIMessagePart<UIDataTypes, UITools>[]
      | ((ctx: unknown) => void),
    events: ChatEvent[],
    messages?: readonly UIMessage[],
    toolCalls?: {
      name: string;
      toolCallId: string;
      input: unknown;
      output: unknown;
      approved?: boolean;
      denied?: boolean;
    }[]
  ): UIMessagePart<UIDataTypes, UITools>[] {
    if (typeof input === "string") {
      const writer = createEventWriter<DataTypes, ToolSet>(
        events,
        writerContext
      );
      writer.text(input);
      return materializeParts(events);
    }
    if (typeof input === "function") {
      const writer = createEventWriter<DataTypes, ToolSet>(
        events,
        writerContext
      );
      const callbackContext: Record<string, unknown> = { writer };
      if (messages !== undefined) {
        callbackContext.messages = messages;
      }
      if (toolCalls !== undefined) {
        callbackContext.toolCall = toolCalls.at(-1);
        callbackContext.toolCalls = toolCalls;
      }
      input(callbackContext as never);
      reserveFromEvents(events);
      return materializeParts(events);
    }
    const cloned = deepClone(input);
    const newEvents = eventsFromParts(cloned);
    reserveFromEvents(newEvents);
    events.push(...newEvents);
    return cloned;
  }

  // Hydrate from options.messages
  if (options.messages) {
    for (const msg of options.messages) {
      const cloned = deepClone(msg) as unknown as UIMessage;
      const events = eventsFromParts(cloned.parts);
      ids.reserveMessageId(cloned.id);
      reserveFromEvents(events);
      turns.push({
        events,
        message: cloned,
        messageId: cloned.id,
        metadata: cloned.metadata,
        role: cloned.role === "user" ? "user" : "assistant",
      });
    }
  }
  const builder: AiSdkChat = {
    assistant(
      input:
        | string
        | UIMessagePart<UIDataTypes, UITools>[]
        | ((ctx: unknown) => void) = DEFAULT_TEXT,
      opts: ChatAssistantOptions<unknown> = {}
    ) {
      const events = flushPendingSleeps();
      const isContinuation = hasContinuation(turns);
      if (typeof input === "function" && isContinuation) {
        // Continuation turn: defer materialization until transcript arrives.
        const id = nextMessageIdOrReserve(opts.id);
        const metadata =
          opts.metadata === undefined ? undefined : deepClone(opts.metadata);
        return pushTurn({
          continuation: true,
          events,
          messageId: id,
          metadata,
          resolve: input,
          role: "assistant",
        });
      }
      if (isContinuation) {
        events.push({ kind: "step-start" });
      }
      const parts = materializeAssistantInput(input, events);
      const metadata =
        opts.metadata === undefined
          ? createMetadata()
          : deepClone(opts.metadata);
      const id = nextMessageIdOrReserve(opts.id);
      const message = defaultCreateMessage({
        id,
        metadata,
        parts,
        role: "assistant",
      });
      return pushTurn({
        events,
        message,
        messageId: id,
        metadata,
        role: "assistant",
        ...(isContinuation ? { continuation: true } : {}),
      });
    },

    error(errorText = DEFAULT_ERROR) {
      const events: ChatEvent[] = [{ errorText, kind: "error" }];
      const metadata = createMetadata();
      const id = ids.nextMessageId();
      const message = defaultCreateMessage({
        id,
        metadata,
        parts: [],
        role: "assistant",
      });
      return pushTurn({
        events,
        message,
        messageId: id,
        metadata,
        role: "assistant",
      });
    },

    get(count?: number): UIMessage[] {
      const firstContinuation = turns.findIndex((t) => t.resolve !== undefined);
      const total = firstContinuation === -1 ? turns.length : firstContinuation;
      const n = count === undefined ? total : count;
      if (!Number.isInteger(n) || n < 0) {
        throw new RangeError("count must be a non-negative integer.");
      }
      if (firstContinuation !== -1 && n > firstContinuation) {
        throw new Error(
          "get() cannot materialize a continuation turn without a live transcript."
        );
      }
      return turns.slice(0, n).map((t) => deepClone(t.message as UIMessage));
    },

    next(messages: readonly UIMessage[]): UIMessage | null {
      const turn = findNextUser(messages);
      return turn?.message ? deepClone(turn.message) : null;
    },

    sleep(delayMs: number) {
      pendingSleeps.push({ delayMs, kind: "sleep", phase: "before-start" });
      return builder;
    },

    transport(
      transportOpts: ChatTransportOptions<
        UIMessage,
        UIMessagePart<UIDataTypes, UITools>
      > = {}
    ): ChatTransport<UIMessage> {
      const lastIdx = lastAssistantIndex(turns, turns.length);
      const lastTurn = turns[lastIdx];
      if (
        lastTurn &&
        !lastTurn.resolve &&
        getPendingToolsRaw(lastTurn.events).some((p) => p.approval)
      ) {
        // Dev warning only â€” no continuation turn follows, decision will be lost.
        // See reference behavior: silently ignore in production.
      }
      const streamOpts = { delayMs: 50, ...transportOpts };
      const { fallback } = transportOpts;
      return {
        async reconnectToStream() {
          return null;
        },
        async sendMessages({ messages, messageId, abortSignal }) {
          const regenerateId =
            messageId !== undefined && messageId !== null
              ? messageId
              : undefined;
          const idx = resolveTurnIndex(
            turns,
            messages,
            matchTranscript,
            regenerateId
          );
          const turn = idx === -1 ? undefined : turns[idx];
          if (!turn) {
            if (fallback !== undefined) {
              const fallbackTurn = buildFallbackResponse(
                fallback as never,
                messages,
                writerContext,
                createMetadata,
                ids,
                materializeAssistantInput
              );
              const envelope = eventsToEnvelope(fallbackTurn.events, {
                delayMs: streamOpts.delayMs,
                messageId: fallbackTurn.messageId,
                messageMetadata: fallbackTurn.metadata,
              });
              return streamFromEnvelope(
                envelope,
                (chunk) => chunk,
                abortSignal ?? undefined
              );
            }
            throw new Error("No assistant response found for this transcript.");
          }
          const envelope = eventsToEnvelope(turn.events, {
            delayMs: streamOpts.delayMs,
            messageId: turn.continuation ? undefined : turn.messageId,
            messageMetadata: turn.metadata,
          });
          return streamFromEnvelope(
            envelope,
            (chunk) => chunk,
            abortSignal ?? undefined
          );
        },
      };
    },
    user(text = DEFAULT_USER_TEXT, opts: ChatUserOptions<unknown> = {}) {
      const events = flushPendingSleeps();
      const localEvents: ChatEvent[] = [
        { id: "text-1", kind: "text", options: { mode: "instant" }, text },
      ];
      for (const file of opts.files ?? []) {
        const cloned = deepClone(file);
        const { type: _type, ...rest } = cloned;
        localEvents.push({ kind: "file", part: rest });
      }
      const parts = materializeParts(localEvents);
      events.push(...localEvents);
      const metadata =
        opts.metadata === undefined
          ? createMetadata()
          : deepClone(opts.metadata);
      const id = nextMessageIdOrReserve(opts.id);
      const message = defaultCreateMessage({
        id,
        metadata,
        parts,
        role: "user",
      });
      return pushTurn({
        events,
        message,
        messageId: id,
        metadata,
        role: "user",
      });
    },
  };

  return builder;
}

// Frakment chat engine — ChatEvent <-> UIMessagePart <-> UIMessageChunk conversion.
// Exports: materializeParts, eventsFromParts, eventsToEnvelope, textStreamEnvelope.

import type {
  ChatEvent,
  ChatEventEnvelope,
  UIDataTypes,
  UIMessageChunk,
  UIMessagePart,
  UITools,
} from "./types";
import { assertNever, splitWords, stripDataPrefix } from "./utils";

// ============================================================
// materializeParts (I) — convert ChatEvent[] → UIMessagePart[]
// ============================================================

function upsertPart(
  parts: UIMessagePart<UIDataTypes, UITools>[],
  part: UIMessagePart<UIDataTypes, UITools>
): void {
  if ("id" in part && part.id) {
    const existing = parts.findIndex(
      (p) => p.type === part.type && "id" in p && p.id === part.id
    );
    if (existing !== -1) {
      parts[existing] = part;
      return;
    }
  }
  parts.push(part);
}

function findToolIndex(
  parts: UIMessagePart<UIDataTypes, UITools>[],
  toolCallId: string
): number {
  return parts.findIndex(
    (p) =>
      (p.type === "dynamic-tool" || p.type.startsWith("tool-")) &&
      "toolCallId" in p &&
      p.toolCallId === toolCallId
  );
}

export function materializeParts(
  events: readonly ChatEvent[]
): UIMessagePart<UIDataTypes, UITools>[] {
  const parts: UIMessagePart<UIDataTypes, UITools>[] = [];
  for (const event of events) {
    switch (event.kind) {
      case "text": {
        parts.push({
          state: "done",
          text: event.text,
          type: "text",
        } as UIMessagePart<UIDataTypes, UITools>);
        break;
      }
      case "reasoning": {
        parts.push({
          state: "done",
          text: event.text,
          type: "reasoning",
        } as UIMessagePart<UIDataTypes, UITools>);
        break;
      }
      case "data": {
        if (event.transient) {
          break;
        }
        upsertPart(parts, {
          data: event.data,
          id: event.id,
          type: `data-${event.name}`,
        } as UIMessagePart<UIDataTypes, UITools>);
        break;
      }
      case "tool-input": {
        upsertPart(parts, {
          type: event.dynamic ? "dynamic-tool" : `tool-${event.name}`,
          ...(event.dynamic ? { toolName: event.name } : {}),
          input: event.input,
          providerExecuted: event.providerExecuted,
          state: "input-available",
          title: event.title,
          toolCallId: event.toolCallId,
          toolMetadata: event.toolMetadata,
        } as UIMessagePart<UIDataTypes, UITools>);
        break;
      }
      case "tool-approval-request": {
        const idx = findToolIndex(parts, event.toolCallId);
        if (idx !== -1) {
          parts[idx] = {
            ...parts[idx],
            approval: { id: event.approvalId },
            state: "approval-requested",
          } as UIMessagePart<UIDataTypes, UITools>;
        }
        break;
      }
      case "tool-output": {
        const idx = findToolIndex(parts, event.toolCallId);
        if (idx !== -1) {
          parts[idx] = {
            ...parts[idx],
            output: event.output,
            preliminary: event.preliminary,
            providerExecuted: event.providerExecuted,
            state: "output-available",
            toolMetadata: event.toolMetadata,
          } as UIMessagePart<UIDataTypes, UITools>;
        }
        break;
      }
      case "tool-error": {
        const idx = findToolIndex(parts, event.toolCallId);
        if (idx !== -1) {
          parts[idx] = {
            ...parts[idx],
            errorText: event.errorText,
            providerExecuted: event.providerExecuted,
            state: "output-error",
            toolMetadata: event.toolMetadata,
          } as UIMessagePart<UIDataTypes, UITools>;
        }
        break;
      }
      case "tool-denied": {
        const idx = findToolIndex(parts, event.toolCallId);
        if (idx !== -1) {
          parts[idx] = {
            ...parts[idx],
            state: "output-denied",
          } as UIMessagePart<UIDataTypes, UITools>;
        }
        break;
      }
      case "source-url": {
        parts.push({ ...event.part, type: "source-url" } as UIMessagePart<
          UIDataTypes,
          UITools
        >);
        break;
      }
      case "source-document": {
        parts.push({ ...event.part, type: "source-document" } as UIMessagePart<
          UIDataTypes,
          UITools
        >);
        break;
      }
      case "file": {
        parts.push({ ...event.part, type: "file" } as UIMessagePart<
          UIDataTypes,
          UITools
        >);
        break;
      }
      case "reasoning-file": {
        parts.push({ ...event.part, type: "reasoning-file" } as UIMessagePart<
          UIDataTypes,
          UITools
        >);
        break;
      }
      case "custom": {
        parts.push({ ...event.part, type: "custom" } as UIMessagePart<
          UIDataTypes,
          UITools
        >);
        break;
      }
      case "step-start": {
        parts.push({ type: "step-start" } as UIMessagePart<
          UIDataTypes,
          UITools
        >);
        break;
      }
      case "sleep":
      case "error": {
        break;
      }
      default: {
        // exhaustiveness check
        const _exhaustive: never = event;
        void _exhaustive;
      }
    }
  }
  return parts;
}

// ============================================================
// eventsFromParts (M) — UIMessagePart[] → ChatEvent[]
// ============================================================

export function eventsFromParts(
  parts: readonly UIMessagePart<UIDataTypes, UITools>[]
): ChatEvent[] {
  const events: ChatEvent[] = [];
  for (const part of parts) {
    switch (part.type) {
      case "text": {
        events.push({
          id: `text-${events.length + 1}`,
          kind: "text",
          options: { mode: "instant" },
          text: (part as { text: string }).text,
        });
        break;
      }
      case "reasoning": {
        events.push({
          id: `reasoning-${events.length + 1}`,
          kind: "reasoning",
          options: { mode: "instant" },
          text: (part as { text: string }).text,
        });
        break;
      }
      default: {
        if (part.type.startsWith("data-")) {
          const dataPart = part as {
            type: string;
            id?: string;
            data?: unknown;
          };
          events.push({
            data: dataPart.data,
            id: dataPart.id,
            kind: "data",
            name: stripDataPrefix(dataPart.type),
          });
        } else if (part.type.startsWith("tool-") && "toolCallId" in part) {
          const toolPart = part as {
            type: string;
            toolCallId: string;
            title?: string;
            toolMetadata?: Record<string, unknown>;
            providerExecuted?: boolean;
            state: string;
            input?: unknown;
            output?: unknown;
            errorText?: string;
            approval?: { id: string };
          };
          const toolName = toolPart.type.replace("tool-", "");
          events.push({
            input: toolPart.input ?? {},
            kind: "tool-input",
            name: toolName,
            providerExecuted: toolPart.providerExecuted,
            title: toolPart.title,
            toolCallId: toolPart.toolCallId,
            toolMetadata: toolPart.toolMetadata,
          });
          if (
            (toolPart.state === "approval-requested" ||
              toolPart.state === "approval-responded") &&
            toolPart.approval
          ) {
            events.push({
              approvalId: toolPart.approval.id,
              kind: "tool-approval-request",
              toolCallId: toolPart.toolCallId,
            });
          }
          if (toolPart.state === "output-available") {
            events.push({
              kind: "tool-output",
              output: toolPart.output,
              providerExecuted: toolPart.providerExecuted,
              toolCallId: toolPart.toolCallId,
              toolMetadata: toolPart.toolMetadata,
            });
          }
          if (toolPart.state === "output-error") {
            events.push({
              errorText: toolPart.errorText ?? "",
              kind: "tool-error",
              providerExecuted: toolPart.providerExecuted,
              toolCallId: toolPart.toolCallId,
              toolMetadata: toolPart.toolMetadata,
            });
          }
          if (toolPart.state === "output-denied") {
            events.push({
              kind: "tool-denied",
              toolCallId: toolPart.toolCallId,
            });
          }
        } else if (part.type === "dynamic-tool") {
          const dynPart = part as {
            toolName: string;
            toolCallId: string;
            title?: string;
            toolMetadata?: Record<string, unknown>;
            providerExecuted?: boolean;
            state: string;
            input?: unknown;
            output?: unknown;
            errorText?: string;
            approval?: { id: string };
          };
          events.push({
            dynamic: true,
            input: dynPart.input ?? {},
            kind: "tool-input",
            name: dynPart.toolName,
            providerExecuted: dynPart.providerExecuted,
            title: dynPart.title,
            toolCallId: dynPart.toolCallId,
            toolMetadata: dynPart.toolMetadata,
          });
          if (dynPart.state === "output-available") {
            events.push({
              dynamic: true,
              kind: "tool-output",
              output: dynPart.output,
              providerExecuted: dynPart.providerExecuted,
              toolCallId: dynPart.toolCallId,
              toolMetadata: dynPart.toolMetadata,
            });
          }
          if (dynPart.state === "output-error") {
            events.push({
              dynamic: true,
              errorText: dynPart.errorText ?? "",
              kind: "tool-error",
              providerExecuted: dynPart.providerExecuted,
              toolCallId: dynPart.toolCallId,
              toolMetadata: dynPart.toolMetadata,
            });
          }
        } else if (part.type === "source-url") {
          events.push({ kind: "source-url", part: part as never });
        } else if (part.type === "source-document") {
          events.push({ kind: "source-document", part: part as never });
        } else if (part.type === "file") {
          events.push({ kind: "file", part: part as never });
        } else if (part.type === "reasoning-file") {
          events.push({ kind: "reasoning-file", part: part as never });
        } else if (part.type === "custom") {
          events.push({ kind: "custom", part: part as never });
        } else if (part.type === "step-start") {
          events.push({ kind: "step-start" });
        }
      }
    }
  }
  return events;
}

// ============================================================
// textStreamEnvelope (Y) — append text/reasoning chunks + sleeps
// ============================================================

export interface EnvelopeContext {
  delayMs?: number;
  messageId?: string;
  messageMetadata?: unknown;
}

function textStreamEnvelope(
  out: ChatEventEnvelope[],
  event: Extract<ChatEvent, { kind: "text" } | { kind: "reasoning" }>,
  context: EnvelopeContext
): void {
  const isText = event.kind === "text";
  const startType = isText ? "text-start" : "reasoning-start";
  const deltaType = isText ? "text-delta" : "reasoning-delta";
  const endType = isText ? "text-end" : "reasoning-end";

  out.push({
    chunk: { id: event.id, type: startType } as UIMessageChunk,
    kind: "chunk",
  });

  const deltas =
    event.options?.mode === "instant" ? [event.text] : splitWords(event.text);
  const delay = event.options?.delayMs ?? context.delayMs;

  for (const delta of deltas) {
    if (delay) {
      out.push({ delayMs: delay, kind: "sleep" });
    }
    out.push({
      chunk: { delta, id: event.id, type: deltaType } as UIMessageChunk,
      kind: "chunk",
    });
  }

  out.push({
    chunk: { id: event.id, type: endType } as UIMessageChunk,
    kind: "chunk",
  });
}

// ============================================================
// eventsToEnvelope (q) — ChatEvent[] → ChatEventEnvelope[]
// ============================================================

export function eventsToEnvelope(
  events: readonly ChatEvent[],
  context: EnvelopeContext
): ChatEventEnvelope[] {
  const out: ChatEventEnvelope[] = [];
  let start = 0;

  // Hoist leading "before-start" sleeps before the start chunk
  for (;;) {
    const ev = events[start];
    if (!(ev && ev.kind === "sleep" && ev.phase === "before-start")) {
      break;
    }
    out.push({ delayMs: ev.delayMs, kind: "sleep" });
    start += 1;
  }

  out.push({
    chunk: { messageId: context.messageId, type: "start" } as UIMessageChunk,
    kind: "chunk",
  });

  for (let i = start; i < events.length; i += 1) {
    const event = events[i];
    if (!event) {
      break;
    }
    switch (event.kind) {
      case "sleep": {
        out.push({ delayMs: event.delayMs, kind: "sleep" });
        break;
      }
      case "text":
      case "reasoning": {
        textStreamEnvelope(out, event, context);
        break;
      }
      case "data": {
        out.push({
          chunk: {
            data: event.data,
            id: event.id,
            name: event.name,
            transient: event.transient,
            type: `data-${event.name}`,
          } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "tool-input": {
        out.push({
          chunk: {
            dynamic: event.dynamic,
            input: event.input,
            providerExecuted: event.providerExecuted,
            title: event.title,
            toolCallId: event.toolCallId,
            toolMetadata: event.toolMetadata,
            toolName: event.name,
            type: "tool-input-available",
          } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "tool-approval-request": {
        out.push({
          chunk: {
            approvalId: event.approvalId,
            toolCallId: event.toolCallId,
            type: "tool-approval-request",
          } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "tool-output": {
        out.push({
          chunk: {
            dynamic: event.dynamic,
            output: event.output,
            preliminary: event.preliminary,
            providerExecuted: event.providerExecuted,
            toolCallId: event.toolCallId,
            toolMetadata: event.toolMetadata,
            type: "tool-output-available",
          } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "tool-error": {
        out.push({
          chunk: {
            dynamic: event.dynamic,
            errorText: event.errorText,
            providerExecuted: event.providerExecuted,
            toolCallId: event.toolCallId,
            toolMetadata: event.toolMetadata,
            type: "tool-output-error",
          } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "tool-denied": {
        out.push({
          chunk: {
            toolCallId: event.toolCallId,
            type: "tool-output-denied",
          } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "error": {
        out.push(
          {
            chunk: {
              errorText: event.errorText,
              type: "error",
            } as UIMessageChunk,
            kind: "chunk",
          },
          { kind: "close" }
        );
        return out;
      }
      case "source-url": {
        out.push({
          chunk: { type: "source-url", ...event.part } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "source-document": {
        out.push({
          chunk: { type: "source-document", ...event.part } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "file": {
        out.push({
          chunk: { type: "file", ...event.part } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "reasoning-file": {
        out.push({
          chunk: { type: "reasoning-file", ...event.part } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "custom": {
        out.push({
          chunk: { type: "custom", ...event.part } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      case "step-start": {
        out.push({
          chunk: { type: "start-step" } as UIMessageChunk,
          kind: "chunk",
        });
        break;
      }
      default: {
        assertNever(event);
      }
    }
  }

  out.push(
    {
      chunk: {
        finishReason: "stop",
        messageMetadata: context.messageMetadata,
        type: "finish",
      } as UIMessageChunk,
      kind: "chunk",
    },
    { kind: "close" }
  );
  return out;
}

// Frakment chat engine — deterministic ID generator (reserve/next semantics).

import type { ChatIdsOptions } from "./types";

export interface IdGenerator {
  nextApprovalId: () => string;
  nextMessageId: () => string;
  nextSourceId: () => string;
  nextToolCallId: () => string;
  reserveApprovalId: (id: string) => void;
  reserveMessageId: (id: string) => void;
  reserveSourceId: (id: string) => void;
  reserveToolCallId: (id: string) => void;
}

interface Counter {
  next: () => string;
  reserve: (id: string) => void;
}

function createCounter(prefix: string): Counter {
  const seen = new Set<string>();
  let max = 0;

  function reserve(id: string): void {
    seen.add(id);
    const expectedPrefix = `${prefix}-`;
    if (!id.startsWith(expectedPrefix)) {
      return;
    }
    const suffix = id.slice(expectedPrefix.length);
    if (!/^\d+$/u.test(suffix)) {
      return;
    }
    const numeric = Number(suffix);
    if (Number.isSafeInteger(numeric)) {
      max = Math.max(max, numeric);
    }
  }

  function next(): string {
    let candidate: string;
    do {
      max += 1;
      candidate = `${prefix}-${max}`;
    } while (seen.has(candidate));
    reserve(candidate);
    return candidate;
  }

  return { next, reserve };
}

export function createIdGenerator(options: ChatIdsOptions = {}): IdGenerator {
  const messageCounter = createCounter(options.messageIdPrefix ?? "msg");
  const toolCallCounter = createCounter(options.toolCallIdPrefix ?? "call");
  const sourceCounter = createCounter(options.sourceIdPrefix ?? "source");
  const approvalCounter = createCounter(options.approvalIdPrefix ?? "approval");

  return {
    nextApprovalId: () => approvalCounter.next(),
    nextMessageId: () => messageCounter.next(),
    nextSourceId: () => sourceCounter.next(),
    nextToolCallId: () => toolCallCounter.next(),
    reserveApprovalId: (id) => approvalCounter.reserve(id),
    reserveMessageId: (id) => messageCounter.reserve(id),
    reserveSourceId: (id) => sourceCounter.reserve(id),
    reserveToolCallId: (id) => toolCallCounter.reserve(id),
  };
}

