export function createPayloadFactory(ids: IdGenerator): PayloadFactory {
  function sourceId(id: string | undefined): string {
    if (id !== undefined) {
      ids.reserveSourceId(id);
      return id;
    }
    return ids.nextSourceId();
  }

  return {
    custom(kind = "test.output", options = {}) {
      return { kind, ...deepClone(options) };
    },
    file(overrides = {}) {
      return {
        filename: "receipt.png",
        mediaType: "image/png",
        url: "https://example.com/receipt.png",
        ...deepClone(overrides),
      };
    },

    reasoningFile(overrides = {}) {
      return {
        mediaType: "text/plain",
        url: "data:text/plain;base64,cmVhc29uaW5n",
        ...deepClone(overrides),
      };
    },

    sourceDocument(overrides = {}) {
      const cloned = deepClone(overrides);
      return {
        filename: cloned.filename,
        mediaType: cloned.mediaType ?? "text/markdown",
        providerMetadata: cloned.providerMetadata,
        sourceId: sourceId(cloned.sourceId),
        title: cloned.title ?? "Retrieved document",
      };
    },

    sourceUrl(overrides = {}) {
      const cloned = deepClone(overrides);
      return {
        providerMetadata: cloned.providerMetadata,
        sourceId: sourceId(cloned.sourceId),
        title: cloned.title ?? "AI SDK Docs",
        url: cloned.url ?? "https://ai-sdk.dev/docs",
      };
    },
  };
}

// Frakment chat engine — ReadableStream<UIMessageChunk> from ChatEventEnvelope[].

import type { ChatEventEnvelope, UIMessageChunk } from "./types";
import { abortableSleep } from "./utils";

export function streamFromEnvelope(
  envelope: readonly ChatEventEnvelope[],
  encodeChunk: (
    chunk: UIMessageChunk
  ) => UIMessageChunk | UIMessageChunk[] | null,
  abortSignal?: AbortSignal
): ReadableStream<UIMessageChunk> {
  let cancelled = false;

  return new ReadableStream<UIMessageChunk>({
    cancel() {
      cancelled = true;
    },
    async start(controller) {
      let aborted = abortSignal?.aborted ?? false;
      const onAbort = () => {
        aborted = true;
      };
      abortSignal?.addEventListener("abort", onAbort);

      function enqueue(chunk: UIMessageChunk): void {
        const encoded = encodeChunk(chunk);
        if (encoded === null) {
          return;
        }
        if (Array.isArray(encoded)) {
          for (const c of encoded) {
            controller.enqueue(c);
          }
          return;
        }
        controller.enqueue(encoded);
      }

      try {
        function finalize(): void {
          if (aborted) {
            enqueue({ reason: "aborted", type: "abort" } as UIMessageChunk);
          }
          controller.close();
        }

        for (const item of envelope) {
          if (cancelled) {
            return;
          }
          if (aborted) {
            finalize();
            return;
          }
          if (item.kind === "sleep") {
            await abortableSleep(item.delayMs, abortSignal);
            if (aborted) {
              finalize();
              return;
            }
            continue;
          }
          if (item.kind === "close") {
            controller.close();
            return;
          }
          enqueue(item.chunk);
        }
        if (!cancelled) {
          controller.close();
        }
      } finally {
        abortSignal?.removeEventListener("abort", onAbort);
      }
    },
  });
}

